SELECT BillingCountry, AVG(Total) AS AverageInvoiceTotal
FROM Invoice
GROUP BY BillingCountry;

SELECT LastName, FirstName
FROM Employee
WHERE ReportsTo = (SELECT ReportsTo FROM Employee WHERE LastName = 'Nancy Edwards');

SELECT PlaylistId, Name
FROM Playlist
WHERE TrackId > 1000;

SELECT species, body_mass_g, AVG(body_mass_g) AS average_mass
FROM penguins
GROUP BY species;

SELECT species, MIN(bill_depth_mm), MAX(bill_depth_mm) AS max_bill_depth
FROM penguins
GROUP BY species;

SELECT species, AVG(bill_length_mm / bill_depth_mm) AS ratio
FROM penguins
GROUP BY species;

SELECT rank, species, bill_length_mm
FROM penguins
ORDER BY bill_length_mm DESC;

SELECT species, body_mass_g, STDDEV(body_mass_g) AS standard_deviation
FROM penguins
GROUP BY species;
